import assert from "node:assert/strict";
import { SearchDriver } from "./runtime/sources/common/src/simulation/search_driver";
import { getA19NeuralState } from "./runtime/sources/common/src/simulation/a19_neural";
import { collected } from "./hooks";
import { digest } from "./io";
let spec: any = null, intervention: any = null;
export function configureBranch(value: any) { spec = value; intervention = null; }
export const branchReceipt = () => intervention;
const p = SearchDriver.prototype as any, applies = p.appliesTo, finals = new WeakMap<any, any>();
function choose(this: any, u: any, ...args: any[]) {
    const chosen = finals.get(this).call(this, u, ...args);
    if (!spec || intervention || u.getId() !== spec.root.actor.id || this.deps.fightProperties.getCurrentLap() !== spec.root.lap) return chosen;
    assert.equal(u.getCumulativeHp(), spec.root.actor.hp);
    assert.equal(digest(chosen), digest(spec.root.chosen));
    const observed = collected().observations.at(-1);
    assert.equal(digest(observed), digest(spec.root), "Root instrumentation must reproduce before intervention");
    intervention = { actor: observed.actor, lap: observed.lap, from: chosen, to: spec.alternative.actions, matchedRootExactly: true };
    return spec.alternative.actions;
}
p.appliesTo = function (...args: any[]) {
    const result = applies.apply(this, args);
    if (getA19NeuralState(this) && !finals.has(this)) {
        finals.set(this, this.chooseDecision);
        Object.defineProperty(this, "chooseDecision", { value: choose, configurable: true, writable: true });
    }
    return result;
};

select-branches.ts.source:
import assert from "node:assert/strict";
import { read, save, digest } from "./io";
const branches: any[] = [];
for (const task of read("cases.json")) for (const seat of [0, 1]) for (const future of [0, 1]) {
    const id = `${task.id}-s${seat}-f${future}`, row = read(`pilot/${id}-observe.json.gz`);
    assert(row.qualityPassed);
    for (const root of row.observations) {
        if (!root.danger) continue;
        const scored = root.scores.filter((s: any) => s.mode === "turns").at(-1);
        if (!scored) continue;
        const options = scored.candidates.map((c: any, i: number) => {
            const samples = root.samples.filter((s: any) => s.mode === "turns" && s.key === JSON.stringify(c.actions) && s.after && Number.isFinite(s.value));
            return { actions: c.actions, i, mean: scored.means[i], samples, net: samples.reduce((n: number, s: any) => n + s.enemyLost - s.ownLost, 0) / 2 };
        }).filter((o: any) => digest(o.actions) !== digest(root.chosen) && Number.isFinite(o.mean) && o.samples.length === 2 &&
            new Set(o.samples.map((s: any) => s.repeat)).size === 2 &&
            o.samples.every((s: any) => s.after.actorHp > 0 && s.enemyLost > 0 && s.ownLost <= s.enemyLost))
            .sort((a: any, b: any) => b.mean - a.mean || b.net - a.net || a.i - b.i);
        if (options.length) { branches.push({ id, task, seat, future, root, alternative: options[0] }); break; }
    }
}
save("branches.json", branches);
save("branch-selection.json", { eligibleCases: branches.length, rule: read("branch-registration.json").selection, allBaselineCasesInspected: 216, combatOutcomesNotUsed: true });
console.log(JSON.stringify({ branches: branches.length }));

