import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { draft, actualOpening } from "./runtime/opening";
import { play } from "./runtime/play";
import { configure, collected } from "./hooks";
import { configureBranch, branchReceipt } from "./branch-hooks";
import { P, read, save, sha, digest } from "./io";
const reg = read("branch-registration.json"), [workerText, workersText] = process.argv.slice(2), worker = Number(workerText), workers = Number(workersText);
for (const [file, hash] of Object.entries(reg.hashes)) assert.equal(sha(readFileSync(join(P, file))), hash);
const jobs = read("branches.json");
for (let i = worker; i < jobs.length; i += workers) {
    assert(Date.now() < reg.cutoffUnix * 1000);
    const job = jobs[i], baseline = read(`pilot/${job.id}-observe.json.gz`);
    configure("off", 0); configureBranch(null);
    const opening = actualOpening(draft(job.task), job.seat ? job.task.reverseSetup : job.task.setup, !!job.seat);
    assert.equal(digest(opening), digest(baseline.opening));
    configure("observe", opening.candidateTeam); configureBranch(job);
    const result = play(opening, job.task.evalFutures[job.future]);
    assert(result.qualityPassed, result.error); assert(branchReceipt()?.matchedRootExactly);
    const prefix = baseline.turns.findIndex((t: any) => t.unitId === job.root.actor.id && t.lap === job.root.lap);
    // The public turn rows may name their actor inside a nested object; preserve the complete traces
    // for independent prefix validation instead of treating an absent convenience key as proof.
    save(`branches/${job.id}.json.gz`, { ...result, ...collected(), job, opening, intervention: branchReceipt(), baselineTraceAvailable: true, candidatePrefixIndex: prefix });
    console.log(JSON.stringify({ completed: job.id }));
}

