import assert from "node:assert/strict";
import { readFileSync, statfsSync } from "node:fs";
import { join } from "node:path";
import { draft, actualOpening } from "./runtime/opening";
import { play } from "./runtime/play";
import { assertPackageIdentity } from "./runtime/identity";
import { configure, collected } from "./hooks";
import { P, read, save, sha, digest } from "./io";
const reg = read("registration.json");
for (const [file, hash] of Object.entries(reg.hashes)) assert.equal(sha(readFileSync(join(P, file))), hash, file);
assertPackageIdentity();
const [host, workerText, workersText, stage = "pilot"] = process.argv.slice(2), worker = Number(workerText), workers = Number(workersText);
assert(["local", "hft"].includes(host));
const families = read("cases.json");
const jobs = families.flatMap((task: any, index: number) => [0, 1].flatMap(seat => [0, 1].map(future => ({ task, index, seat, future, id: `${task.id}-s${seat}-f${future}` }))));
const selected = stage === "cold" ? jobs.filter((x: any) => [0, 18, 36].includes(x.index) && x.seat === 0 && x.future === 0) : jobs.filter((x: any) => x.index % 2 === (host === "local" ? 0 : 1));
for (let j = worker; j < selected.length; j += workers) {
    const job = selected[j];
    const rows: any = {};
    for (const mode of (job.index + job.seat + job.future) % 2 ? ["candidate", "observe"] : ["observe", "candidate"]) {
        assert(Date.now() < reg.cutoffUnix * 1000, "Fixed study cutoff");
        const fs = statfsSync(P); assert(fs.bavail * fs.bsize > 2 * 1024 ** 3);
        configure("off", 0);
        const opening = actualOpening(draft(job.task), job.seat ? job.task.reverseSetup : job.task.setup, !!job.seat);
        configure(mode, opening.candidateTeam);
        const result = play(opening, job.task.evalFutures[job.future]);
        assert(result.qualityPassed, result.error);
        const row = { ...result, opening, ...collected(), job, host, mode, registrationSha256: sha(readFileSync(join(P, "registration.json"))) };
        save(`${stage}/${job.id}-${mode}.json.gz`, row);
        rows[mode] = row;
        if (stage === "cold") {
            const prior = read(`pilot/${job.id}-${mode}.json.gz`);
            for (const field of ["opening", "result", "turns", "events", "health", "observations"]) assert.equal(digest(row[field]), digest(prior[field]), field);
        }
    }
    assert.equal(digest(rows.observe.opening), digest(rows.candidate.opening));
    save(`${stage}/complete-${job.id}.json`, { qualityPassed: true, job, host });
    console.log(JSON.stringify({ stage, host, worker, completed: job.id }));
}

verify-analysis.ts.source:
import assert from "node:assert/strict";
import { read, save } from "./io";
const summary = read("analysis.json"), families = read("cases.json"), sums: number[] = [];
let better = 0, worse = 0, tied = 0;
for (const family of families) {
    let delta = 0;
    for (const seat of [0, 1]) for (const future of [0, 1]) {
        const score = (mode: string) => {
            const r = read(`pilot/${family.id}-s${seat}-f${future}-${mode}.json.gz`);
            assert(r.qualityPassed && r.receipt.qualityPassed);
            return r.result.winner === "draw" ? 1 : r.result.winner === (r.candidateTeam === 2 ? "green" : "red") ? 2 : 0;
        };
        const d = score("candidate") - score("observe");
        delta += d;
        if (d > 0) better++; else if (d < 0) worse++; else tied++;
    }
    sums.push(delta);
}
const mean = sums.reduce((a, b) => a + b, 0) / (8 * sums.length) * 100;
let state = 17112026;
function next() { state ^= state << 13; state ^= state >>> 17; state ^= state << 5; return state >>> 0; }
const resamples: number[] = [];
for (let b = 0; b < 20000; b++) {
    let value = 0;
    for (let i = 0; i < sums.length; i++) value += sums[next() % sums.length];
    resamples.push(value / (8 * sums.length) * 100);
}
resamples.sort((a, b) => a - b);
const interval = [resamples[500], resamples[19500]];
assert(Math.abs(mean - summary.meanScoreGainPp) < 1e-12);
interval.forEach((x, i) => assert(Math.abs(x - summary.familyBootstrap95Pp[i]) < 1e-12));
assert.equal(better, summary.counters.better_cases ?? 0);
assert.equal(worse, summary.counters.worse_cases ?? 0);
assert.equal(tied, summary.counters.tied_cases ?? 0);
const proof = { qualityPassed: true, independentIntegerHalfPointReconstruction: true, families: sums.length, better, worse, tied, meanPp: mean, intervalPp: interval, initialVerifierFailure: "Python Counter omits zero-valued better/worse keys; normalize absent counters to zero. No input, policy or result changed." };
save("independent-verification.json", proof);
console.log(JSON.stringify(proof));
